<?php
namespace App\Http\Controllers;
use App\Models\{WaterPoint,Locality,Commune,User,TechnicianProfile,Maintenance,AuditLog};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Inertia\Inertia;
class CatalogController {
 private function manager(Request $r):void{abort_unless($r->user()?->isManager(),403);}
 private function pointAccess(Request $r,WaterPoint $p):void{$this->manager($r);abort_unless($r->user()->role==='admin'||$p->locality->commune_id===$r->user()->commune_id,403);}
 public function points(Request $r){$q=WaterPoint::with('locality.commune','manager:id,name','maintenances:id,water_point_id,scheduled_at,completed_at');if($r->filled('q'))$q->where('name','like','%'.$r->q.'%');if($r->filled('state'))$q->where('state',$r->state);return Inertia::render('Points',['points'=>$q->orderBy('name')->get(),'localities'=>Locality::with('commune')->get(),'filters'=>$r->only('q','state')]);}
 public function savePoint(Request $r,?WaterPoint $point=null){$this->manager($r);if($point?->exists)$this->pointAccess($r,$point);$d=$r->validate(['code'=>'required|string|max:40|unique:water_points,code,'.($point?->id??'NULL'),'name'=>'required|string|max:150','locality_id'=>'required|exists:localities,id','equipment'=>'required|string|max:100','community'=>'required|string|max:150','landmark'=>'nullable|string|max:500','state'=>'required|in:fonctionnel,degrade,hors_service,inconnu']);$l=Locality::findOrFail($d['locality_id']);abort_unless($r->user()->role==='admin'||$l->commune_id===$r->user()->commune_id,403);if($point?->exists)$point->update($d+['state_updated_at'=>now()]);else WaterPoint::create($d+['manager_id'=>$r->user()->id,'state_updated_at'=>now()]);return back()->with('message','Point d’eau enregistré.');}
 public function technicians(Request $r){abort_unless(in_array($r->user()->role,['admin','gestionnaire','relais','technicien']),403);$q=TechnicianProfile::with('user:id,name','zones')->whereHas('user',fn($u)=>$u->where('role','technicien'));if($r->user()->role!=='admin')$q->whereHas('zones',fn($x)=>$x->where('communes.id',$r->user()->commune_id));return Inertia::render('Technicians',['technicians'=>$q->get(),'communes'=>Commune::all()]);}
 public function availability(Request $r,TechnicianProfile $profile){abort_unless($r->user()->role==='admin'||$r->user()->id===$profile->user_id,403);$d=$r->validate(['availability'=>'required|in:disponible,occupe,indisponible']);$profile->update($d);return back()->with('message','Disponibilité actualisée.');}
 public function maintenance(Request $r){abort_unless(in_array($r->user()->role,['admin','gestionnaire','relais','technicien']),403);$q=Maintenance::with('waterPoint.locality','responsible:id,name');$p=WaterPoint::with('locality');$u=User::query()->whereIn('role',['technicien','gestionnaire','relais','admin']);if($r->user()->role!=='admin'){$q->whereHas('waterPoint.locality',fn($x)=>$x->where('commune_id',$r->user()->commune_id));$p->whereHas('locality',fn($x)=>$x->where('commune_id',$r->user()->commune_id));$u->where('commune_id',$r->user()->commune_id);}if($r->user()->role==='technicien')$q->where('responsible_id',$r->user()->id);return Inertia::render('Maintenance',['maintenances'=>$q->orderBy('scheduled_at')->get(),'points'=>$p->get(),'users'=>$u->get(['id','name'])]);}
 public function storeMaintenance(Request $r){$this->manager($r);$d=$r->validate(['water_point_id'=>'required|exists:water_points,id','responsible_id'=>'required|exists:users,id','scheduled_at'=>'required|date|after_or_equal:today','operations'=>'required|string|min:5|max:2000']);$p=WaterPoint::findOrFail($d['water_point_id']);$this->pointAccess($r,$p);$u=User::findOrFail($d['responsible_id']);abort_unless(in_array($u->role,['technicien','gestionnaire','relais','admin']) && ($u->role==='admin'||$u->commune_id===$p->locality->commune_id),422,'Responsable hors périmètre.');Maintenance::create($d);return back()->with('message','Entretien programmé.');}
 public function finishMaintenance(Request $r,Maintenance $maintenance){$this->pointAccessOrResponsible($r,$maintenance);$d=$r->validate(['report'=>'required|string|min:5|max:3000']);$maintenance->update($d+['completed_at'=>now()]);return back()->with('message','Entretien réalisé enregistré.');}
 private function pointAccessOrResponsible(Request $r,Maintenance $m){abort_unless($r->user()->id===$m->responsible_id || ($r->user()->isManager()&&($r->user()->role==='admin'||$m->waterPoint->locality->commune_id===$r->user()->commune_id)),403);}
 public function admin(Request $r){abort_unless($r->user()->role==='admin',403);return Inertia::render('Admin',['users'=>User::with('profile')->orderBy('name')->get(),'communes'=>Commune::all(),'localities'=>Locality::with('commune')->get(),'logs'=>AuditLog::latest()->limit(50)->get()]);}
 public function saveUser(Request $r){abort_unless($r->user()->role==='admin',403);$d=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|unique:users,email','password'=>'required|string|min:12','role'=>'required|in:usager,relais,gestionnaire,technicien,admin','commune_id'=>'required|exists:communes,id','phone'=>'required_if:role,technicien|nullable|string|max:24','skills'=>'required_if:role,technicien|nullable|string|max:500','referenced'=>'nullable|boolean']);DB::transaction(function()use($d){$u=User::create(collect($d)->only('name','email','password','role','commune_id')->all());if($d['role']==='technicien'){$p=TechnicianProfile::create(['user_id'=>$u->id,'phone'=>$d['phone'],'skills'=>array_map('trim',explode(',',$d['skills'])),'referenced'=>$d['referenced']??false]);$p->zones()->attach($d['commune_id']);}AuditLog::create(['user_id'=>auth()->id(),'action'=>'creation_utilisateur','subject'=>'user:'.$u->id]);});return back()->with('message','Compte créé.');}
 public function updateUser(Request $r,User $user){
 abort_unless($r->user()->role==='admin',403);
 $d=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|unique:users,email,'.$user->id,'password'=>'nullable|string|min:12','role'=>'required|in:usager,relais,gestionnaire,technicien,admin','commune_id'=>'required|exists:communes,id','phone'=>'required_if:role,technicien|nullable|string|max:24','skills'=>'required_if:role,technicien|nullable|string|max:500','referenced'=>'nullable|boolean']);
 abort_if($user->id===$r->user()->id&&$d['role']!=='admin',422,'Vous ne pouvez pas retirer votre propre rôle administrateur.');
 DB::transaction(function()use($user,$d,$r){$fields=collect($d)->only('name','email','role','commune_id')->all();if(!empty($d['password']))$fields['password']=$d['password'];$user->update($fields);if($d['role']==='technicien'){$p=TechnicianProfile::updateOrCreate(['user_id'=>$user->id],['phone'=>$d['phone'],'skills'=>array_map('trim',explode(',',$d['skills'])),'referenced'=>$d['referenced']??false]);$p->zones()->sync([$d['commune_id']]);}AuditLog::create(['user_id'=>$r->user()->id,'action'=>'modification_utilisateur','subject'=>'user:'.$user->id]);});return back()->with('message','Compte actualisé.');
 }
 public function saveLocality(Request $r){abort_unless($r->user()->role==='admin',403);$d=$r->validate(['name'=>'required|string|max:100','commune_id'=>'nullable|exists:communes,id']);if(empty($d['commune_id']))Commune::create(['name'=>$d['name']]);else Locality::firstOrCreate($d);return back()->with('message','Référentiel enregistré.');}
}
